import React, { useState, useEffect } from 'react';
import {
  ChartBarIcon,
  ShieldCheckIcon,
  ExclamationTriangleIcon,
  InformationCircleIcon,
  ArrowTrendingUpIcon,
  ArrowTrendingDownIcon,
  CalendarIcon,
  DocumentTextIcon
} from '@heroicons/react/24/outline';
import api from '../services/api';
import { useNotification } from '../hooks/useNotification';
import { format, subDays, startOfDay, endOfDay } from 'date-fns';
import { es } from 'date-fns/locale';

const DMARCReportsPanel = ({ domainId = null, showHeader = true, timeRange = 7 }) => {
  const [reports, setReports] = useState([]);
  const [statistics, setStatistics] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selectedPeriod, setSelectedPeriod] = useState(timeRange);
  const { showNotification } = useNotification();

  useEffect(() => {
    fetchReports();
    fetchStatistics();
  }, [domainId, selectedPeriod]);

  const fetchReports = async () => {
    try {
      setLoading(true);
      let url = '/api/dmarc-reports/';
      const params = new URLSearchParams();

      if (domainId) {
        params.append('domain', domainId);
      }

      // Filtrar por período
      const endDate = new Date();
      const startDate = subDays(endDate, selectedPeriod);
      params.append('date_from', format(startOfDay(startDate), 'yyyy-MM-dd'));
      params.append('date_to', format(endOfDay(endDate), 'yyyy-MM-dd'));
      params.append('ordering', '-report_date');
      params.append('limit', '10');

      if (params.toString()) {
        url += '?' + params.toString();
      }

      const response = await api.get(url);
      setReports(response.data.results || response.data);
    } catch (error) {
      console.error('Error fetching DMARC reports:', error);
      showNotification('Error al cargar los reportes DMARC', 'error');
    } finally {
      setLoading(false);
    }
  };

  const fetchStatistics = async () => {
    try {
      let url = '/api/dmarc-reports/statistics/';
      const params = new URLSearchParams();

      if (domainId) {
        params.append('domain', domainId);
      }

      const endDate = new Date();
      const startDate = subDays(endDate, selectedPeriod);
      params.append('date_from', format(startOfDay(startDate), 'yyyy-MM-dd'));
      params.append('date_to', format(endOfDay(endDate), 'yyyy-MM-dd'));

      if (params.toString()) {
        url += '?' + params.toString();
      }

      const response = await api.get(url);
      setStatistics(response.data);
    } catch (error) {
      console.error('Error fetching DMARC statistics:', error);
    }
  };

  const calculatePassRate = (report) => {
    const total = report.dmarc_pass + report.dmarc_fail;
    return total > 0 ? ((report.dmarc_pass / total) * 100).toFixed(1) : 0;
  };

  const getPassRateColor = (rate) => {
    if (rate >= 95) return 'text-green-600';
    if (rate >= 80) return 'text-yellow-600';
    return 'text-red-600';
  };

  const getPassRateIcon = (rate) => {
    if (rate >= 95) return <ShieldCheckIcon className="h-5 w-5 text-green-500" />;
    if (rate >= 80) return <ExclamationTriangleIcon className="h-5 w-5 text-yellow-500" />;
    return <ExclamationTriangleIcon className="h-5 w-5 text-red-500" />;
  };

  const formatNumber = (num) => {
    if (num >= 1000000) {
      return (num / 1000000).toFixed(1) + 'M';
    }
    if (num >= 1000) {
      return (num / 1000).toFixed(1) + 'K';
    }
    return num.toString();
  };

  const periodOptions = [
    { value: 7, label: 'Últimos 7 días' },
    { value: 30, label: 'Últimos 30 días' },
    { value: 90, label: 'Últimos 90 días' }
  ];

  if (loading) {
    return (
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
        {showHeader && (
          <h3 className="text-lg font-medium text-gray-900 mb-4">Reportes DMARC</h3>
        )}
        <div className="animate-pulse space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {[...Array(3)].map((_, i) => (
              <div key={i} className="bg-gray-200 h-20 rounded"></div>
            ))}
          </div>
          <div className="space-y-3">
            {[...Array(3)].map((_, i) => (
              <div key={i} className="h-16 bg-gray-200 rounded"></div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200">
      {showHeader && (
        <div className="px-6 py-4 border-b border-gray-200">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-medium text-gray-900">Reportes DMARC</h3>

            <div className="flex items-center space-x-2">
              <select
                value={selectedPeriod}
                onChange={(e) => setSelectedPeriod(parseInt(e.target.value))}
                className="text-sm border-gray-300 rounded-md focus:ring-primary-500 focus:border-primary-500"
              >
                {periodOptions.map(option => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </div>
      )}

      <div className="p-6">
        {/* Estadísticas generales */}
        {statistics && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
            <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
              <div className="flex items-center">
                <div className="flex-shrink-0">
                  <DocumentTextIcon className="h-8 w-8 text-blue-600" />
                </div>
                <div className="ml-4">
                  <div className="text-sm font-medium text-blue-900">
                    Total de Reportes
                  </div>
                  <div className="text-2xl font-bold text-blue-600">
                    {statistics.total_reports || 0}
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-green-50 border border-green-200 rounded-lg p-4">
              <div className="flex items-center">
                <div className="flex-shrink-0">
                  <ShieldCheckIcon className="h-8 w-8 text-green-600" />
                </div>
                <div className="ml-4">
                  <div className="text-sm font-medium text-green-900">
                    Tasa de Aprobación
                  </div>
                  <div className="text-2xl font-bold text-green-600">
                    {statistics.average_pass_rate ? `${statistics.average_pass_rate.toFixed(1)}%` : '0%'}
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-purple-50 border border-purple-200 rounded-lg p-4">
              <div className="flex items-center">
                <div className="flex-shrink-0">
                  <ChartBarIcon className="h-8 w-8 text-purple-600" />
                </div>
                <div className="ml-4">
                  <div className="text-sm font-medium text-purple-900">
                    Total de Mensajes
                  </div>
                  <div className="text-2xl font-bold text-purple-600">
                    {formatNumber(statistics.total_messages || 0)}
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Lista de reportes */}
        {reports.length === 0 ? (
          <div className="text-center py-8">
            <DocumentTextIcon className="mx-auto h-12 w-12 text-gray-400" />
            <h3 className="mt-2 text-sm font-medium text-gray-900">
              No hay reportes DMARC
            </h3>
            <p className="mt-1 text-sm text-gray-500">
              No se han recibido reportes DMARC en el período seleccionado.
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            <h4 className="text-sm font-medium text-gray-900 mb-3">
              Reportes Recientes
            </h4>

            {reports.map((report) => {
              const passRate = parseFloat(calculatePassRate(report));
              const totalMessages = report.dmarc_pass + report.dmarc_fail;

              return (
                <div
                  key={report.id}
                  className="border border-gray-200 rounded-lg p-4 hover:bg-gray-50 transition-colors"
                >
                  <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-4">
                      <div className="flex-shrink-0">
                        {getPassRateIcon(passRate)}
                      </div>

                      <div className="flex-1 min-w-0">
                        <div className="flex items-center space-x-2 mb-1">
                          <h5 className="text-sm font-medium text-gray-900 truncate">
                            {report.reporter_org_name || 'Reporte DMARC'}
                          </h5>

                          <span className={`text-sm font-medium ${
                            getPassRateColor(passRate)
                          }`}>
                            {passRate}% aprobación
                          </span>
                        </div>

                        <div className="flex items-center text-xs text-gray-500 space-x-4">
                          <span className="flex items-center">
                            <CalendarIcon className="h-3 w-3 mr-1" />
                            {format(new Date(report.report_date), 'dd MMM yyyy', { locale: es })}
                          </span>

                          <span>
                            {formatNumber(totalMessages)} mensajes
                          </span>

                          {report.domain_name && (
                            <span>Dominio: {report.domain_name}</span>
                          )}
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center space-x-4 text-sm">
                      {/* Estadísticas DMARC */}
                      <div className="text-center">
                        <div className="text-xs text-gray-500">DMARC</div>
                        <div className="flex items-center space-x-1">
                          <span className="text-green-600 font-medium">
                            {formatNumber(report.dmarc_pass)}
                          </span>
                          <span className="text-gray-400">/</span>
                          <span className="text-red-600 font-medium">
                            {formatNumber(report.dmarc_fail)}
                          </span>
                        </div>
                      </div>

                      {/* Estadísticas SPF */}
                      <div className="text-center">
                        <div className="text-xs text-gray-500">SPF</div>
                        <div className="flex items-center space-x-1">
                          <span className="text-green-600 font-medium">
                            {formatNumber(report.spf_pass)}
                          </span>
                          <span className="text-gray-400">/</span>
                          <span className="text-red-600 font-medium">
                            {formatNumber(report.spf_fail)}
                          </span>
                        </div>
                      </div>

                      {/* Estadísticas DKIM */}
                      <div className="text-center">
                        <div className="text-xs text-gray-500">DKIM</div>
                        <div className="flex items-center space-x-1">
                          <span className="text-green-600 font-medium">
                            {formatNumber(report.dkim_pass)}
                          </span>
                          <span className="text-gray-400">/</span>
                          <span className="text-red-600 font-medium">
                            {formatNumber(report.dkim_fail)}
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Barra de progreso */}
                  <div className="mt-3">
                    <div className="flex items-center justify-between text-xs text-gray-500 mb-1">
                      <span>Tasa de aprobación DMARC</span>
                      <span>{passRate}%</span>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-2">
                      <div
                        className={`h-2 rounded-full transition-all duration-300 ${
                          passRate >= 95 ? 'bg-green-500' :
                          passRate >= 80 ? 'bg-yellow-500' : 'bg-red-500'
                        }`}
                        style={{ width: `${Math.min(passRate, 100)}%` }}
                      ></div>
                    </div>
                  </div>

                  {/* Detalles adicionales */}
                  {report.policy_disposition && (
                    <div className="mt-2 text-xs text-gray-500">
                      Política aplicada: 
                      <span className="ml-1 font-medium">
                        {report.policy_disposition}
                      </span>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}

        {/* Enlace para ver todos los reportes */}
        {reports.length > 0 && (
          <div className="mt-6 text-center">
            <a
              href={`/reports${domainId ? `?domain=${domainId}` : ''}`}
              className="text-sm text-primary-600 hover:text-primary-800 font-medium"
            >
              Ver todos los reportes →
            </a>
          </div>
        )}

        {/* Información adicional */}
        {statistics && statistics.total_reports === 0 && (
          <div className="mt-6 bg-blue-50 border border-blue-200 rounded-lg p-4">
            <div className="flex">
              <InformationCircleIcon className="h-5 w-5 text-blue-400 flex-shrink-0" />
              <div className="ml-3">
                <h4 className="text-sm font-medium text-blue-800">
                  ¿No ves reportes DMARC?
                </h4>
                <div className="mt-2 text-sm text-blue-700">
                  <p className="mb-2">
                    Los reportes DMARC pueden tardar hasta 24-48 horas en llegar después de configurar los registros DNS.
                  </p>
                  <ul className="list-disc list-inside space-y-1">
                    <li>Verifica que el registro DMARC esté correctamente configurado</li>
                    <li>Asegúrate de que el email de reportes (rua) sea válido</li>
                    <li>Los proveedores de correo envían reportes diariamente</li>
                  </ul>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DMARCReportsPanel;
